{
  "chunk_id": "exec-10-1",
  "command": "cd /app/documents && perl -MIO::Uncompress::Inflate -e '
for my $f (glob "*.pdf") {
  print "===== $f =====\n";
  open my $fh, "<:raw", $f or die;
  local $/; my $d = <$fh>; close $fh;
  my $found = 0;
  while ($d =~ /stream\r?\n(.*?)endstream/sg) {
    my $chunk = $1;
    my $out;
    if (Inflate(\$chunk, \$out)) { 
      # extract text in parens and hex
      while ($out =~ /\(([^()]*)\)/g) { my $s=$1; $s =~ s/\\(.)/$1/g; print "$s " if $s =~ /\S/; $found=1; }
      print "\n---stream---\n";
    }
  }
  print "(no decoded text)\n" unless $found;
  print "\n";
}' 2>&1 | head -120",
